import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{name:string,params:any,trigger?:string}>} [cinematicPrimitives]
 * @property {Array<{text:string, role?:string, typography?:{fontSize?:number}}>} [textContent]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Object} [intent.visualSpec.textContent]
 * @property {Object} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{ loadTexture(url:string):Promise<any> }} textureLoader
 * @property {{ loadGLB(url:string):Promise<any> }} glbLoader
 * @property {{ videoLoader?: { loadVideo(url:string):Promise<any> } }} videoLoader
 * @property {{ createText(content:string, opts?:any):any }} fontAtlas
 * @property {{ [key:string]: (target:any, params:any) => { cleanup:()=>void, timeline?:any } }} primitives
 * @property {(event:string, payload:any)=>void} emit
 * @property {string} [tier]
 */

/**
 * Creates a journal card label node.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  /** @type {any[]} */
  const disposables = [];

  const root = new Group();

  // ---------- Backdrop (stage) ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();

  // vertical gradient: surface -> paper
  const gradientNode = mix(
    color('#0b0b10'), // surface
    color('#e8ecf2'), // paper
    uv().y
  );
  backdropMat.colorNode = gradientNode;
  backdropMat.transparent = true;

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  disposables.push({
    cleanup() {
      backdropGeom.dispose();
      backdropMat.dispose();
    },
  });

  // ---------- Main Plane ----------
  const aspect = 512 / 320; // image aspect ratio
  const planeWidth = 1.6; // arbitrary size fitting aspect
  const planeHeight = planeWidth / aspect;

  const planeGeom = new PlaneGeometry(planeWidth, planeHeight);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  disposables.push({
    cleanup() {
      planeGeom.dispose();
      planeMat.dispose();
    },
  });

  // Load texture (if provided)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ---------- Text Content ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textGroup = new Group();
  root.add(textGroup);

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.34,
      color: config.colors?.ink ?? '#16161d',
      align: 'center',
    });

    // Position text slightly above the plane
    txt.position.set(0, 0, 0.01);
    textGroup.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      if (instance && typeof instance.cleanup === 'function') {
        disposables.push(instance);
      }
    }
  }

  // ---------- Handlers (none defined) ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Kill GSAP timelines if any were created
    gsap.globalTimeline.clear();

    for (const d of disposables) {
      if (d && typeof d.cleanup === 'function') {
        d.cleanup();
      }
    }

    // Dispose loaded texture if present
    if (planeMat.map && typeof planeMat.map.dispose === 'function') {
      planeMat.map.dispose();
    }
  };

  return root;
}
